def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "close_gate": And([
            Not(self.low_height_scan_performed),
            self.downward_sensors_enabled,
            self.human_presence_possible,
            self.low_height_threshold_configured
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
